<main class="content"><div class="page-actions"><a href="<?=url('/admin/usuarios')?>">← Volver a usuarios</a></div><section class="panel form-page"><div class="panel-head"><div><span class="eyebrow">CUENTA DE USUARIO</span><h2><?=$user?'Editar usuario':'Crear usuario'?></h2><p>Completa los datos, asigna el rol y define los módulos disponibles.</p></div></div><form method="post" action="<?=url('/admin/usuarios/guardar')?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($user['id']??'')?>"><div class="form-grid"><label>Nombre<input required name="first_name" value="<?=e($user['first_name']??'')?>"></label><label>Apellido<input required name="last_name" value="<?=e($user['last_name']??'')?>"></label><label>Correo electrónico<input required type="email" name="email" value="<?=e($user['email']??'')?>"></label><label>Teléfono<input name="phone" value="<?=e($user['phone']??'')?>"></label><label>Rol<select required name="role_id"><?php foreach($roles as $r):?><option value="<?=$r['id']?>" <?=($user['role_id']??null)==$r['id']?'selected':''?>><?=e(ucfirst($r['name']))?></option><?php endforeach;?></select></label><label>Asignatura<select name="subject_id"><option value="">Sin asignatura</option><?php foreach($subjects as $s):?><option value="<?=$s['id']?>" <?=($user['subject_id']??null)==$s['id']?'selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select></label><label class="wide">Contraseña<input type="password" name="password" <?=$user ? "" : "required"?> placeholder="<?=$user?'Déjala vacía para conservar la actual':'Crea una contraseña segura'?>"></label><label class="check"><input type="checkbox" name="test_enabled" value="1" <?=!empty($user['test_enabled'])?'checked':''?>> Habilitar módulo de tests</label><label class="check"><input type="checkbox" name="tabulator_enabled" value="1" <?=!empty($user['tabulator_enabled'])?'checked':''?>> Habilitar módulo de tabuladores</label><input type="hidden" name="active" value="1"></div><div class="form-actions"><a class="secondary" href="<?=url('/admin/usuarios')?>">Cancelar</a><button class="primary">Guardar usuario</button></div></form></section></main>
